		"Turn on Hornet's `hardening.user_enumeration`, or use pollora/headless." => "Włącz w Hornet `hardening.user_enumeration` lub użyj pollora/headless.",
		"The REST API does not list users to visitors." => "REST API nie ujawnia odwiedzającym listy użytkowników.",
		"WordPress version" => "Wersja WordPressa",
